192	/**
193	 * A complete, valid props object for a given variation — narrows on `variation` with a plain
194	 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
195	 * index.tsx's own render body, not to test fixtures).
196	 *
197	 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
198	 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
199	 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
200	 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
201	 * present on every union member." A `test.each` call site passing a runtime (non-literal)
202	 * `variation` still resolves to the final, general overload below.
203	 */
204	function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
205	function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
206	function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
207	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
208	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
209	  const base = {
210	    id: 'p1',
211	    href: '/product/1',
212	    name: 'Natura Dress',
213	    headingLevel: 'h3' as const,
214	    primaryImage: PRIMARY,
215	  };
216	  switch (variation) {
217	    case 'wishlist':
218	      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
219	    case 'home':
220	      return { ...base, variation };
221	    case 'plp':
222	      return { ...base, variation };
223	    default:
224	      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
225	      // not silently falls through to a wrong variation's shape.
226	      return ((): never => {
227	        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
228	      })();
229	  }
230	}
