232	describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
233	  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
234	  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
235	  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
236	  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
237	  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
238	  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
239	    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
240	    const invalid: ZimmProductCardProps = {
241	      id: 'p1',
242	      href: '/product/1',
243	      name: 'Dress',
244	      headingLevel: 'h3',
245	      primaryImage: PRIMARY,
246	      variation: 'wishlist',
247	    };
248	    expect(invalid).toBeDefined();
249	  });
