303	  });
304	});
305	
306	/**
307	 * KNOWN LIMITATION — read before trusting these as proof of the real z-index layering.
308	 *
309	 * Every test below fires a click/keydown directly on the target control's own DOM node via
310	 * Testing Library. That proves the CALLBACK WIRING is correct: the right element calls the right
311	 * handler when it is actually interacted with. It does NOT prove that a real mouse click at that
312	 * screen position, in an actual browser, would land on that control rather than on the invisible
313	 * stretched-link `::after` overlay sitting over the whole card — jsdom performs no real layout,
314	 * paint, or hit-testing (no CSS cascade resolution, no stacking-context/z-index comparison, no
315	 * geometry at all); `fireEvent`/`user-event` dispatch straight to the node you name, bypassing
316	 * whatever a browser's hit-testing algorithm would actually resolve at that (x, y). The
317	 * `zimmProductCard.css.ts` recipe assertions further below prove the CSS this organism emits has
318	 * the right `position`/`z-index` values (verified by literally compiling it through this
319	 * project's real Stylis — see that describe block) — but going from "the right CSS values exist"
320	 * to "a real browser click lands on the right element" is exactly the gap a real-browser
321	 * (Playwright or manual) check is for. Treat this whole file as necessary, not sufficient, proof.
322	 */
323	describe('ZimmProductCard — every interactive control stays separately clickable (wiring only, see limitation above)', () => {
324	  test('the bag button fires onAddToBag independently of the name-link overlay (PLP)', async () => {
325	    const onAddToBag = vi.fn();
